SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(12*10^9);Alarm(650);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");load "work/deg10/continuation_20261031b/Y228_shared/fast_primitive_inverse.m";root:="work/deg10/continuation_20261031b/C56/";outdir:=root cat "kummer_rr/";mdraw:=Read(root cat STEM cat "_model.m");opraw:=Read(root cat STEM cat "_operator_progress.m");md:=eval mdraw;op:=eval opraw;pointrows,cas,inds:=Explode(op);tag:="case"cat IntegerToString(cas[1])cat "_A"cat IntegerToString(pointrows[inds[1]][7]);Write(outdir cat tag cat "_model_snapshot.m",mdraw:Overwrite:=true);Write(outdir cat tag cat "_operator_snapshot.m",opraw:Overwrite:=true);
k:=GF(3);PK:=PolynomialRing(k);K<t>:=FunctionField(k);R<X>:=PolynomialRing(K);
function DR(v)return K!(PK!v[1])/(K!(PK!v[2]));end function;
F<u>:=FunctionField(R![DR(v):v in md[1]]);assert Genus(F) eq 25;OF:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);
function DF(v)return F![DR(a):a in v];end function;
function ER(v)return [[Integers()!a:a in Coefficients(Numerator(v))],[Integers()!a:a in Coefficients(Denominator(v))]];end function;
function EF(v)return [ER(a):a in Eltseq(F!v)];end function;
function PD(p)g,h:=TwoGenerators(p);OO:=IsFinite(p) select OF else OI;assert ideal<OO|g,h> eq Ideal(p);return[*Degree(p),IsFinite(p) select 1 else 0,[EF(g),EF(h)]*];end function;
function DP(v)OO:=v[3] eq 1 select OF else OI;gs:=[DF(a):a in v[4]];II:=ideal<OO|gs>;assert #gs eq 2 and IsPrime(II);p:=Place(II);assert Degree(p) eq v[2];return p;end function;
function KV(v)return Y228PrimitiveJointKey(v);end function;
function CV(v)return [Integers()!a:a in Eltseq(v,k)];end function;
function MM(M)return[*Nrows(M),Ncols(M),[Integers()!a:a in Eltseq(M)]*];end function;
B,C:=Explode([DF(v):v in md[2]]);places:=[];groups:=[* *];
procedure AddTerm(~places,~groups,desc,n,physical)
 p:=DP(desc);ii:=Index(places,p);if ii eq 0 then Append(~places,p);Append(~groups,[*[],[],[* *],[* *]*]);ii:=#places;end if;gr:=groups[ii];key:=Sprint(desc[5]);jj:=Index(gr[1],key);
 if jj eq 0 then Append(~gr[1],key);Append(~gr[2],n);Append(~gr[3],desc);Append(~gr[4],physical);else gr[2][jj]+:=n;end if;groups[ii]:=gr;
end procedure;
for ix in inds do row:=pointrows[ix];Q:=row[7];AddTerm(~places,~groups,row[4],-1,row[9]);AddTerm(~places,~groups,row[6],-Q,row[10]);for h in row[8] do AddTerm(~places,~groups,h[3],h[2],h[4]);end for;end for;
A0:=DivisorGroup(F)!0;ac:=[];ddeg:=0;
for i in[1..#places] do a:=Max([0]cat groups[i][2]);Append(~ac,a);A0+:=a*Divisor(places[i]);for j in[1..#groups[i][2]] do ddeg+:=groups[i][2][j]*groups[i][3][j][1];end for;end for;assert ddeg eq 0;
psB:=Zeros(B) cat Poles(B);Rhalf:=&+[Integers()!Floor(Rationals()!Valuation(B,p)/2)*Divisor(p):p in psB];assert Degree(Rhalf) eq -12;V0,v0:=RiemannRochSpace(A0);V1,v1:=RiemannRochSpace(A0+Rhalf);f0:=[v0(w):w in Basis(V0)];f1:=[v1(w):w in Basis(V1)];n0:=#f0;n1:=#f1;nb:=n0+n1;print "C56_KUMMER_BASE_SPACES",cas[1],Degree(A0),n0,n1,Cputime(tt);Write(outdir cat tag cat "_basis.m",Sprint([*Degree(A0),n0,n1,[EF(f):f in f0],[EF(f):f in f1],[*[*PD(places[i]),ac[i]*]:i in[1..#places]*]*]):Overwrite:=true);
ALL:=ZeroMatrix(k,nb,0);tables:=[* *];
for gi in[1..#places] do
 p:=places[gi];e:=Degree(p);a:=ac[gi];gr:=groups[gi];if a eq 0 and &and[n eq 0:n in gr[2]] then continue;end if;
 physical:=gr[4][1];PF:=PolynomialRing(k);KM<aa>:=ext<k|PF!physical[1]>;decode:=func<v|Evaluate(PF!v,aa)>;E:=EllipticCurve([decode(v):v in physical[2]]);P:=E![decode(v):v in physical[3]];assert Order(P) eq 56;RK<T>:=PolynomialRing(KM);ET,ph:=IsogenyFromKernel(E,T-(28*P)[1]);QQ:=ph(P);dual:=DualIsogeny(ph);ai:=aInvariants(ET);ss:=[ET![r[1],-(ai[1]*r[1]+ai[3])/2]:r in Roots(DivisionPolynomial(ET,2))];S:=[s:s in ss|dual(s) eq E!0][1];bcphys:=DerickxNormalForm_bc(ET,S,QQ);bb,cc:=Explode(bcphys);EE:=EllipticCurve([KM|0,-2*cc,0,cc^2-4*bb*(1-bb-cc),0]);want:=TateNormalForm_bc(E,P);roots:=Roots(RK![-bb,0,1]);assert #roots eq 2;z0s:=[];
 for rr in roots do zr:=rr[1];xx:=2*bb+cc+2*zr;PP:=EE![xx,2*zr*xx];if TateNormalForm_bc(EE,PP) eq want then Append(~z0s,zr);end if;end for;assert #z0s eq 1;z0:=z0s[1];dq:=gr[3][1][1];assert dq in[e,2*e];
 keys:=[* *];coeffs:=[];qdegrees:=[];qsigns:=[];
 for sg in (dq eq e select [1,-1] else [1]) do zr:=sg*z0;xx:=2*bb+cc+2*zr;PP:=EE![xx,2*zr*xx];key:=KV(TateNormalForm_bc(EE,PP));assert key[1] eq dq;idx:=Index(gr[1],Sprint(key));n:=idx eq 0 select 0 else gr[2][idx];Append(~keys,key);Append(~coeffs,n);Append(~qdegrees,dq);Append(~qsigns,sg);end for;assert &and[key in [Sprint(z):z in keys]:key in gr[1]];needs:=[a-n:n in coeffs];assert &and[n ge 0:n in needs];maxneed:=Max(needs);if maxneed eq 0 then continue;end if;
 LS,em:=Completion(F,p:Precision:=120);uni:=LS.1;KP:=CoefficientRing(LS);assert Degree(KP) eq e;bc0:=[Coefficient(em(v),0):v in[B,C]];assert &and[Valuation(em(v)) eq 0:v in[B,C]];chosen:=[];
 for bits in[[1,0],[0,1],[1,1],[1,2]] do gg:=&+[KP!bits[i]*bc0[i]:i in[1,2]];if Degree(MinimalPolynomial(gg,k)) eq e then chosen:=bits;break;end if;end for;assert #chosen eq 2;gm:=&+[KM!chosen[i]*bcphys[i]:i in[1,2]];assert MinimalPolynomial(gm,k) eq MinimalPolynomial(gg,k);IM:=Matrix(k,[Eltseq(gg^i,k):i in[0..e-1]]);sol:=Eltseq(Solution(IM,Vector(k,Eltseq(KP.1,k))));imgen:=&+[KM!sol[i+1]*gm^i:i in[0..e-1]];emb:=hom<KP->KM|imgen>;assert [emb(v):v in bc0] eq bcphys;
 sB:=em(B);BBs:=[emb(Coefficient(sB,n)):n in[0..maxneed-1]];zz:=[z0];
 for n in[1..maxneed-1] do cross:=KM!0;for i in[1..n-1] do cross+:=zz[i+1]*zz[n-i+1];end for;Append(~zz,(BBs[n+1]-cross)/(2*z0));end for;assert &and[&+[zz[i+1]*zz[n-i+1]:i in[0..n]] eq BBs[n+1]:n in[0..maxneed-1]];
 s0:=[uni^a*em(f):f in f0];s1:=[uni^a*em(f):f in f1];assert &and[Valuation(s) ge 0 and AbsolutePrecision(s) ge maxneed:s in s0 cat s1];H0:=[[emb(Coefficient(s,n)):n in[0..maxneed-1]]:s in s0];H1:=[[emb(Coefficient(s,n)):n in[0..maxneed-1]]:s in s1];ZH1:=[[&+[zz[i+1]*row[n-i+1]:i in[0..n]]:n in[0..maxneed-1]]:row in H1];blocks:=[* *];
 for qi in[1..#keys] do need:=needs[qi];if need eq 0 then continue;end if;sg:=qsigns[qi];zr:=sg*z0;xx:=2*bb+cc+2*zr;PP:=EE![xx,2*zr*xx];uv:=TateNormalForm_bc(EE,PP);bits:=keys[qi][2];gq:=&+[KM!bits[i]*uv[i]:i in[1,2]];polq:=MinimalPolynomial(gq,k);assert Degree(polq) eq dq;LQ<vq>:=ext<k|polq>;hq:=hom<LQ->KM|gq>;matrows:=[];
  for row in H0 do vals:=[];for n in[1..need] do val:=row[n]@@hq;assert hq(val) eq row[n];vals cat:=Eltseq(val,k);end for;Append(~matrows,vals);end for;
  for row in ZH1 do vals:=[];for n in[1..need] do value:=sg*row[n];val:=value@@hq;assert hq(val) eq value;vals cat:=Eltseq(val,k);end for;Append(~matrows,vals);end for;
  MM0:=Matrix(k,matrows);assert Nrows(MM0) eq nb and Ncols(MM0) eq dq*need;ALL:=HorizontalJoin(ALL,MM0);Append(~blocks,[*keys[qi],coeffs[qi],sg,dq,need,CV(gq),[Integers()!x:x in Coefficients(polq)],MM(MM0)*]);
 end for;
 Append(~tables,[*PD(p),a,e,[Integers()!x:x in Coefficients(DefiningPolynomial(KM,k))],[CV(v):v in bcphys],CV(z0),[CV(v):v in BBs],[[CV(v):v in row]:row in H0],[[CV(v):v in row]:row in H1],blocks*]);Write(outdir cat tag cat "_jet_tables_progress.m",Sprint(tables):Overwrite:=true);print "C56_KUMMER_LOCAL_BLOCK",cas[1],gi,e,a,needs,Ncols(ALL),Cputime(tt);
end for;
assert Ncols(ALL) eq 2*Degree(A0);rk:=Rank(ALL);h0:=nb-rk;Write(outdir cat tag cat "_jet_tables.m",Sprint(tables):Overwrite:=true);Write(outdir cat tag cat "_result.m",Sprint([*cas[1],pointrows[inds[1]][7],Degree(A0),n0,n1,Ncols(ALL),rk,h0*]):Overwrite:=true);print "D31B_C56_KUMMER_RR_COMPLETE",cas[1],pointrows[inds[1]][7],Degree(A0),n0,n1,Ncols(ALL),rk,h0,Cputime(tt);quit;
